+package com.example;
+
+import java.util.ArrayList;
+import java.util.Collections;
+import java.util.List;
+
+import org.springframework.stereotype.Service;
+
+/** In-memory storage shared by contact view instances for this application run. */
+@Service
+public class ContactMessageService {
+
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public synchronized void add(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    public synchronized List<ContactMessage> newestFirst() {
+        return Collections.unmodifiableList(new ArrayList<>(messages));
+    }
+}
