+package com.example;
+
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> messages = new Grid<>();
+    private final ContactMessageService messageService;
+    private boolean clearingAfterSend;
+
+    public ContactView(ContactMessageService messageService) {
+        this.messageService = messageService;
+
+        H1 heading = new H1("Contact");
+        RouterLink about = new RouterLink("About", AboutView.class);
+
+        FormLayout form = new FormLayout();
+        form.setAutoResponsive(true);
+        form.setExpandColumns(true);
+        form.setExpandFields(true);
+        form.setMaxWidth("42rem");
+        form.add(name, email, phone, message, send);
+
+        messages.addColumn(ContactMessage::name).setHeader("Name");
+        messages.addColumn(ContactMessage::message).setHeader("Message");
+        messages.setWidthFull();
+        refreshMessages();
+
+        send.addClickListener(event -> submit());
+        send.addClickShortcut(Key.ENTER);
+        name.addValueChangeListener(event -> enableAfterEdit());
+        email.addValueChangeListener(event -> enableAfterEdit());
+        phone.addValueChangeListener(event -> enableAfterEdit());
+        message.addValueChangeListener(event -> enableAfterEdit());
+
+        add(heading, about, form, messages);
+    }
+
+    private void enableAfterEdit() {
+        if (!clearingAfterSend) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void submit() {
+        clearValidationErrors();
+        if (!isValid()) {
+            return;
+        }
+
+        messageService.add(new ContactMessage(name.getValue(), email.getValue(),
+                phone.getValue(), message.getValue()));
+        refreshMessages();
+
+        clearingAfterSend = true;
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        clearingAfterSend = false;
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean isValid() {
+        boolean valid = true;
+        if (name.getValue().isBlank()) {
+            name.setInvalid(true);
+            name.setErrorMessage("Name is required");
+            valid = false;
+        }
+
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        if (!emailValue.isEmpty() && !isValidEmail(emailValue)) {
+            email.setInvalid(true);
+            email.setErrorMessage("Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            email.setInvalid(true);
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        String messageValue = message.getValue();
+        if (messageValue.isBlank()) {
+            message.setInvalid(true);
+            message.setErrorMessage("Message is required");
+            valid = false;
+        } else if (messageValue.length() > 500) {
+            message.setInvalid(true);
+            message.setErrorMessage("Message must be at most 500 characters");
+            valid = false;
+        }
+        return valid;
+    }
+
+    private boolean isValidEmail(String value) {
+        return value.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+    }
+
+    private void clearValidationErrors() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+    }
+
+    private void refreshMessages() {
+        messages.setItems(messageService.newestFirst());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.getValue().isEmpty() || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty() || !message.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+        Dialog confirmation = new Dialog();
+        Button keepEditing = new Button("Keep editing", click -> confirmation.close());
+        Button discard = new Button("Discard", click -> {
+            confirmation.close();
+            action.proceed();
+        });
+        confirmation.add(new Paragraph("Discard the message you are editing?"), keepEditing, discard);
+        confirmation.open();
+    }
+}
