+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void validatesSendsAndGuardsNavigation() {
+        navigate(ContactView.class);
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+        Button send = find(Button.class).withText("Send").single();
+
+        test(send).click();
+        assertThat(name.isInvalid()).isTrue();
+        assertThat(name.getErrorMessage()).isEqualTo("Name is required");
+        assertThat(email.getErrorMessage()).isEqualTo("Give an e-mail address or a phone number");
+        assertThat(message.getErrorMessage()).isEqualTo("Message is required");
+
+        test(name).setValue("Ada");
+        test(email).setValue("ada@example.com");
+        test(message).setValue("Hello");
+        fireShortcut(Key.ENTER);
+
+        Grid<ContactMessage> grid = find(Grid.class).single();
+        assertThat(test(grid).size()).isEqualTo(1);
+        assertThat(test(grid).getRow(0).message()).isEqualTo("Hello");
+        assertThat(send.isEnabled()).isFalse();
+        assertThat(name.getValue()).isEmpty();
+        test(email).setValue("another@example.com");
+        assertThat(send.isEnabled()).isTrue();
+
+        test(find(RouterLink.class).withText("About").single()).click();
+        assertThat(find(Dialog.class).exists()).isTrue();
+        test(find(Button.class).withText("Keep editing").single()).click();
+        assertThat(getCurrentView()).isInstanceOf(ContactView.class);
+
+        test(find(RouterLink.class).withText("About").single()).click();
+        test(find(Button.class).withText("Discard").single()).click();
+        assertThat(getCurrentView()).isInstanceOf(AboutView.class);
+    }
+}
